/*
 * NES — a filesystem app.
 *
 * Every file here came out of your Dragon86 filesystem over /9pf/, the same
 * way a website would: jsnes.min.js and test.nes are read from
 * ~/system/apps/nes/. Replace test.nes with a ROM you own and reload.
 *
 * jsnes is Apache-2.0 (see LICENSE.jsnes); the ROM is generated by
 * tools/make-test-rom.py in the Dragon86 repo — it exists to prove the
 * emulator is rendering and ticking, nothing else.
 */

const W = 256;
const H = 240;
const canvas = document.getElementById("screen");
const ctx2d = canvas.getContext("2d", { alpha: false });
const image = ctx2d.createImageData(W, H);
const err = document.getElementById("err");

const failure = (msg) => {
  err.textContent = msg;
  console.error(msg);
};

if (!window.jsnes) {
  failure("jsnes.min.js did not load — is the app folder intact?");
} else {
  const jsnes = window.jsnes;

  const nes = new jsnes.NES({
    onFrame(buffer) {
      const out = image.data;
      for (let i = 0, p = 0; i < W * H; i++, p += 4) {
        const v = buffer[i];
        out[p] = (v >> 16) & 0xff;
        out[p + 1] = (v >> 8) & 0xff;
        out[p + 2] = v & 0xff;
        out[p + 3] = 255;
      }
      ctx2d.putImageData(image, 0, 0);
    },
    onAudioSample() {
      /* silent for now: audio needs a user gesture and a buffer schedule */
    },
    onStatusChanged() {},
  });

  const BUTTONS = {
    A: jsnes.Controller.BUTTON_A,
    B: jsnes.Controller.BUTTON_B,
    SELECT: jsnes.Controller.BUTTON_SELECT,
    START: jsnes.Controller.BUTTON_START,
    UP: jsnes.Controller.BUTTON_UP,
    DOWN: jsnes.Controller.BUTTON_DOWN,
    LEFT: jsnes.Controller.BUTTON_LEFT,
    RIGHT: jsnes.Controller.BUTTON_RIGHT,
  };
  const KEYMAP = {
    ArrowUp: "UP", ArrowDown: "DOWN", ArrowLeft: "LEFT", ArrowRight: "RIGHT",
    w: "UP", s: "DOWN", a: "LEFT", d: "RIGHT",
    z: "A", x: "B", Enter: "START", Shift: "SELECT",
  };

  const press = (name, down) => {
    const b = BUTTONS[name];
    if (b === undefined) return;
    if (down) nes.buttonDown(1, b);
    else nes.buttonUp(1, b);
  };

  window.addEventListener("keydown", (e) => {
    const name = KEYMAP[e.key];
    if (!name) return;
    e.preventDefault();
    press(name, true);
  });
  window.addEventListener("keyup", (e) => {
    const name = KEYMAP[e.key];
    if (!name) return;
    e.preventDefault();
    press(name, false);
  });

  for (const el of document.querySelectorAll("[data-btn]")) {
    const name = el.dataset.btn;
    const down = (e) => {
      e.preventDefault();
      el.classList.add("on");
      press(name, true);
    };
    const up = (e) => {
      e.preventDefault();
      el.classList.remove("on");
      press(name, false);
    };
    el.addEventListener("pointerdown", down);
    el.addEventListener("pointerup", up);
    el.addEventListener("pointercancel", up);
    el.addEventListener("pointerleave", up);
  }

  /* One emulated frame per animation frame: the ROM is a test pattern, so
     accuracy matters more than catching up. */
  let running = false;
  const tick = () => {
    if (!running) return;
    try {
      nes.frame();
    } catch (e) {
      running = false;
      failure("the ROM stopped: " + (e && e.message ? e.message : e));
      return;
    }
    requestAnimationFrame(tick);
  };

  fetch("./test.nes")
    .then((r) => (r.ok ? r.arrayBuffer() : Promise.reject(new Error("HTTP " + r.status))))
    .then((buffer) => {
      const bytes = new Uint8Array(buffer);
      let rom = "";
      for (let i = 0; i < bytes.length; i += 0x8000) {
        rom += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
      }
      nes.loadROM(rom);
      running = true;
      requestAnimationFrame(tick);
    })
    .catch((e) => failure("could not read test.nes: " + e.message));
}
